```latex
\section{Preliminaries}
\label{section:preliminaries}

\subsection{Basic graph terminology}
In this work, all graphs considered are undirected multigraphs (i.e., they may have parallel edges).
Let $G=(V,E)$ be a graph. We let $V(G)$ and $E(G)$ denote the vertex-set and the edge-set of $G$, respectively.

A \emph{path} $P$ in $G$ is an alternating sequence $x_1,e_1,\dots,x_{k-1},e_{k-1},x_k$, with $k\geq 1$, of vertices and edges of $G$, starting with a vertex $x_1$ and ending with a vertex $x_k$, such that $e_i=(x_i,x_{i+1})$ for every $i\in\{1,\dots,k-1\}$.
For every two vertices $x$ and $y$ of $G$, we say that $x$ is connected with $y$ if there is a path from $x$ to $y$ in $G$. In particular, if $V(G)$ is the only connected component of $G$, then $G$ is called a \emph{connected} graph.

An edge-minimal cut $C$ is a set of edges with the property that $G\setminus C$ is disconnected, but $G\setminus C'$ is connected for every proper subset $C'$ of $C$. From now on, the term ``cut" will always mean ``edge-minimal cut". A cut with $k$ edges is called a $k$-cut.

\subsection{Notation}
For any two sets $A$ and $B$ such that $A\cap B=\emptyset$, we use the notation $A\sqcup B$ to denote the union $A\cup B$, while emphasizing the fact that $A\cap B=\emptyset$. Also, whenever we use the expression $A\subset B$, we imply that $A$ is a \emph{proper} subset of $B$ (and thus $A\neq B$). Otherwise, if $A=B$ is allowed, then we write $A\subseteq B$.

If $L$ is a sorted list of elements and $x$ is an element in $L$, we use $\mathit{next}_L(x)$ and $\mathit{prev}_L(x)$ to denote the successor and the predecessor, respectively, of $x$ in $L$. We use $\bot$ to denote the end-of-list element.

\section{Concepts defined on DFS-tree}
\label{section:DFS}

\subsection{Basic definitions}
\label{subsection:basic-dfs}
Let $T$ be a DFS-tree of $G$ with start vertex $r$.
For a vertex $v\neq r$ of $G$, we let $p(v)$ denote the parent of $v$ on $T$.
If $v$ lies on the tree-path $T[r,u]$, then we say that $v$ is an ancestor of $u$ (equivalently, $u$ is a descendant of $v$).
If $v$ is an ancestor of $u$ such that $v\neq u$, then we say that $v$ is a proper ancestor of $u$ (equivalently, $u$ is a proper descendant of $v$).

Every non-tree of $G$ has its endpoints related as ancestor and descendant on $T$ \cite{DBLP:journals/siamcomp/Tarjan72}. Thus, the non-tree edges of $G$ are called ``back-edges". Whenever we let $(x,y)$ denote a back-edge, we always assume that $x$ is the higher endpoint of $(x,y)$ (i.e., $x>y$). For a vertex $v\neq r$, we say that a back-edge $(x,y)$ leaps over $v$ if $x$ is a descendant of $v$ and $y$ is a proper ancestor of $v$. We let $B(v)$ denote the set of the back-edges that leap over $v$.

Let $v\neq r$ be a vertex. We let $\mathit{bcount}(v)$ denote the number of back-edges that leap over $v$ (i.e., $\mathit{bcount}(v)=|B(v)|$).

\subsubsection{$\mathit{low}$ and $\mathit{high}$ edges}
Now let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in increasing order w.r.t. their lower endpoint. Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{low}_i$-edge of $v$, for every $i\in\{1,\dots,k\}$. The lower endpoint of the $\mathit{low}_i$-edge of $v$ is called the $\mathit{low}_i$ point of $v$, and we denote it as $\mathit{low}_i(v)$ (i.e., we have $\mathit{low}_i(v)=y_i$). Of particular importance is the $\mathit{low}_1$ point of $v$, which we may simply denote as $\mathit{low}(v)$.

Now let $v$ be a vertex, and let $c_1,\dots,c_t$ be the children of $v$ sorted in increasing order w.r.t. their $\mathit{low}$ point (breaking ties arbitrarily). In other words, we have $\mathit{low}(c_1)\leq\dots\leq\mathit{low}(c_t)$. Then we call $c_i$ the $\mathit{lowi}$ child of $v$.

Now let $v\neq r$ be a vertex, and let $(x_1,y_1),\dots,(x_k,y_k)$ be the list of the back-edges in $B(v)$ sorted in decreasing order w.r.t. their lower endpoint. Then (w.r.t. this sorting) we call $(x_i,y_i)$ the $\mathit{high}_i$-edge of $v$, for every $i\in\{1,\dots,k\}$. The lower endpoint of the $\mathit{high}_i$-edge of $v$ is called the $\mathit{high}_i$ point of $v$, and we denote it as $\mathit{high}_i(v)$ (i.e., we have $\mathit{high}_i(v)=y_i$). If we want to reference the $\mathit{high}_i$-edge of $v$ with its endpoints, then we denote it as $(\mathit{highD}_i(v),\mathit{high}_i(v))$. Of particular importance is the $\mathit{high}_1$ point of $v$, which we may simply denote as $\mathit{high}(v)$. Also, we denote the $\mathit{high}_1$-edge of $v$ as $e_\mathit{high}(v)$.

\subsubsection{Maximum points, leftmost and rightmost edges}
Let $v\neq r$ be a vertex. We let $M(v)$ denote the maximum vertex that is an ancestor of the higher endpoints of the back-edges in $B(v)$.
For every vertex $x$, we let $M^{-1}(x)$ denote the list of all vertices $v$ with $M(v)=x$, sorted in decreasing order. For every vertex $v\in M^{-1}(x)$, we let $\mathit{nextM}(v)$ and $\mathit{prevM}(v)$ denote the successor and the predecessor, respectively, of $v$ in $M^{-1}(x)$.

We extend the concept of the $M$ points in general sets of back-edges. Thus, if $S$ is a set of back-edges, then we let $M(S)$ denote the nearest common ancestor of the higher endpoints of the back-edges in $S$. Let $c$ be a descendant of a vertex $v\neq r$, and let $S$ be the set of the back-edges that leap over $v$ and stem from the subtree of $c$ (i.e., $S=\{(x,y)\in B(v)\mid x\mbox{ is a descendant of }c\}$). Then we denote $M(S)$ as $M(v,c)$.

\subsection{Properties of the DFS parameters}
\label{subsection:dfs-properties}

\begin{lemma}
\label{lemma:same_m_subset_B}
Let $u$ and $v$ be two vertices $\neq r$ such that $v$ is an ancestor of $u$ and $M(v)$ is a descendant of $M(u)$. Then $B(v)\subseteq B(u)$.
\end{lemma}

\begin{proposition}[\cite{DBLP:conf/esa/GeorgiadisIK21}]
\label{proposition:3-edge-conn}
$G$ is $3$-edge-connected if and only if: for every vertex $v\neq r$ we have $\mathit{bcount}(v)>1$, and for every two distinct vertices $u$ and $v$ such that $r\notin\{u,v\}$ we have $B(u)\neq B(v)$.
\end{proposition}

\begin{lemma}
\label{lemma:w-v-u-not-related}
Let $w\neq r$ be a vertex, and let $u$ and $v$ be two descendants of $w$ such that $M(u)=M(w,x)\neq\bot$ and $M(v)=M(w,y)\neq\bot$, where $x$ and $y$ are descendants of different children of $M(w)$. Then $u$ and $v$ are not related as ancestor and descendant.
\end{lemma}

\subsection{Computing the $M$ points}
\label{subsection:M}

\begin{proposition}
\label{proposition:computing-M(v,c)}
Let $(v_1,c_1),\dots,(v_N,c_N)$ be a sequence of pairs of vertices such that $v_i\neq r$ and $c_i$ is a descendant of $v_i$, for every $i\in\{1,\dots,N\}$. Then the values $M(v_1,c_1),\dots,M(v_N,c_N)$ can be computed in $O(m+N)$ time in total.
\end{proposition}

\section{Computing a complete collection of $4$-cuts}
\label{section:computing-4-cuts}

\subsection{Min-max vertex queries}
\label{subsection:mim-max-queries}

It is straightforward to modify Algorithm~\ref{algorithm:W-queries} appropriately, so that we get an algorithm for answering the reverse type of queries (i.e., those that ask for the lowest vertex that is greater than another vertex), with or without equality. 

\begin{lemma}
\label{lemma:W-queries}
Let $W_1,\dots,W_k$ be a collection of pairwise disjoint sets of vertices. Let $q(i_1,z_1),\dots,q(i_N,z_N)$ be a set of queries of the form $q(i,z)\equiv$`` given an index $i\in\{1,\dots,k\}$ and a vertex $z$, find the greatest vertex $w\in W_i$ such that $w\leq z$". Then, Algorithm~\ref{algorithm:W-queries} answers all those queries in $O(n+N)$ time. 
\end{lemma}

\begin{algorithm}[t!]
\caption{\textsf{Given a collection $W_1,\dots,W_k$ of pairwise disjoint sets of vertices, answer a set of queries $q(i_1,z_1),\dots,q(i_N,z_N)$, where $q(i_t,z_t)$, for every $t\in\{1,\dots,N\}$, asks for the greatest vertex $w\in W_{i_t}$ such that $w\leq z_t$.}}
\label{algorithm:W-queries}
\LinesNumbered
\DontPrintSemicolon
\tcp{$W_1,\dots,W_k$ is a collection of pairwise disjoint sets of vertices}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $W_i$ in decreasing order\;
}
\ForEach{$i\in\{1,\dots,k\}$}{
  initialize $Q(i)\leftarrow\emptyset$\;
}
\ForEach{$t\in\{1,\dots,N\}$}{
  insert a tuple $(z_t,t)$ into $Q(i_t)$\;
}
\tcp{$Q(i)$ contains a tuple of the form $(z,t)$ if and only if the query $q(i_t,z_t)$ has $i_t=i$ and $z_t=z$. The first component of a tuple in $Q(i)$ stores the vertex of the respective query, and the second component stores a pointer to the query. The information, that we have to search in the set $W_i$ for the answer to this query, is given precisely by the index $i$ of this bucket of tuples}
\ForEach{$i\in\{1,\dots,k\}$}{
  sort $Q(i)$ in decreasing order w.r.t. the first component of its elements\; 
}
\ForEach{$i\in\{1,\dots,k\}$}{
\label{line:W-queries-for}
  let $w$ be the first element of $W_i$\;
  let $p$ be the first element of $Q(i)$\;
  \While{$p\neq\bot$}{
    let $p=(z,t)$\;
    \While{$w\neq\bot$ \textbf{and} $w>z$}{
      $w\leftarrow\mathit{next}_{W_i}(w)$\;
    }
    the answer to $q(i_t,z_t)$ is $w$\;
    $p\leftarrow\mathit{next}_{Q(i)}(p)$\;
  }
}
\end{algorithm}

\section{Computing Type-3$\alpha$ $4$-cuts}
\label{section:type-3a}

Throughout this section, we assume that $G$ is a $3$-edge-connected graph with $n$ vertices and $m$ edges. All graph-related elements (e.g., vertices, edges, cuts, etc.) refer to $G$. Furthermore, we assume that we have computed a DFS-tree $T$ of $G$ rooted at a vertex $r$.

\begin{lemma}
\label{lemma:type-3a-types}
Let $u,v,w$ be three vertices $\neq r$ such that $w$ is a common ancestor of $\{u,v\}$, and $u,v$ are not related as ancestor and descendant. Then there is a back-edge $e$ such that $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut if and only if either $(i)$ $e\in B(u)\cup B(v)$ and $B(w)\sqcup\{e\}=B(u)\sqcup B(v)$, or $(ii)$ $B(w)=(B(u)\sqcup B(v))\sqcup \{e\}$.
\end{lemma}

According to Lemma~\ref{lemma:type-3a-types}, we distinguish two types of Type-3$\alpha$ $4$-cuts: Type-3$\alpha i$ and Type-3$\alpha ii$. In both cases, the $4$-cuts that we consider have the form $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$, where $w$ is a common ancestor of $\{u,v\}$, and $u,v$ are not related as ancestor and descendant. In the case of Type-3$\alpha i$ $4$-cuts, we have that $e\in B(u)\sqcup B(v)$ and $B(w)\sqcup\{e\}=B(u)\sqcup B(v)$.

\subsection{Type-3$\alpha i$ $4$-cuts}

\begin{lemma}
\label{lemma:type-3a-lowchild_desc}
Let $u,v,w$ be three vertices such that $w$ is a common ancestor of $\{u,v\}$, and $u,v$ are not related as ancestor and descendant. Suppose that there is a back-edge $e\in B(u)\sqcup B(v)$ such that $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut. Then, either $u$ is a descendant of the $\mathit{low1}$ child of $M(w)$ and $v$ is a descendant of the $\mathit{low2}$ child of $M(w)$, or reversely.
\end{lemma}

Also, throughout this section we let $e(u)$ denote the back-edge $e_\mathit{high}(u)$.

\begin{lemma}
\label{lemma:type-3a-i-M}
Let $u,v,w$ be three vertices such that $w$ is a common ancestor of $\{u,v\}$, and $u,v$ are not related as ancestor and descendant. Suppose that there is a back-edge $e\in B(u)$ such that $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a $4$-cut. Then $e=(\mathit{highD}_1(u),\mathit{high}_1(u))$. Furthermore, suppose that $u$ is a descendant of the $\mathit{low1}$ child $c$ of $M(w)$. Then $M(B(u)\setminus\{e\})=M(w,c)$.
\end{lemma}

A vertex $u$ such that $M(B(u)\setminus\{e(u)\})=M(u)$ is called a ``special" vertex.

\begin{lemma}
\label{lemma:type-3a-i-criterion}
Let $u,v,w$ be three vertices such that $w$ is a common ancestor of $\{u,v\}$, and $u,v$ are not related as ancestor and descendant. Then, there is a back-edge $e\in B(u)$ such that $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$ is a Type-3$\alpha$i $4$-cut if and only if: $\mathit{high}_2(u)<w$, $\mathit{high}_1(v)<w$, and $\mathit{bcount}(w)=\mathit{bcount}(u)+\mathit{bcount}(v)-1$.
\end{lemma}

\begin{algorithm}[H]
\caption{\textsf{Compute all Type-3$\alpha$i $4$-cuts of the form $\{(u,p(u)),(v,p(v)),(w,p(w)),e\}$, where $w$ is a common ancestor of $\{u,v\}$, $e\in B(u)$, and $u$ is a special vertex.}}
\label{algorithm:type3-a-i-special}
\LinesNumbered
\DontPrintSemicolon
\ForEach{vertex $w\neq r$ such that $M(w)$ has at least two children}{
\label{line:type3-a-i-special-for}
compute $M(w,c_1)$ and $M(w,c_2)$, where $c_1$ and $c_2$ are the $\mathit{low1}$ and $\mathit{low2}$ children of $M(w)$, respectively\;
}
\tcp{the case where $u$ is a descendant of the $\mathit{low1}$ child of $M(w)$; for the other case, simply reverse the roles of $c_1$ and $c_2$}
\ForEach{vertex $w\neq r$}{
   \lIf{$M(w)$ has less than two children}{\textbf{continue}}
   let $c_1\leftarrow\mathit{low1}$ child of $M(w)$\;
   \label{line:type3-a-i-special-c1}
   let $c_2\leftarrow\mathit{low2}$ child of $M(w)$\;
   \label{line:type3-a-i-special-c2}
   \lIf{$M(w,c_1)=\bot$ \textbf{or} $M(w,c_2)=\bot$}{\textbf{continue}}
   let $u$ be the lowest proper descendant of $w$ such that $M(u)=M(w,c_1)$\;
   \label{line:type3-a-i-special-u}
   let $v$ be the lowest proper descendant of $w$ such that $M(v)=M(w,c_2)$\;
   \label{line:type3-a-i-special-v}
   \If{$u$ is a special vertex \textbf{and} $\mathit{bcount}(w)=(\mathit{bcount}(u)-1)+\mathit{bcount}(v)$ \textbf{and} $\mathit{high}_2(u)<w$ \textbf{and} $\mathit{high}_1(v)<w$}{
     mark $\{(u,p(u)),(v,p(v)),(w,p(w)),e(u)\}$ as a $4$-cut\;
     \label{line:type3-a-i-special-mark1}
   }
   $u\leftarrow\mathit{prevM}(u)$\;
   \If{$u$ is a special vertex \textbf{and} $\mathit{bcount}(w)=(\mathit{bcount}(u)-1)+\mathit{bcount}(v)$ \textbf{and} $\mathit{high}_2(u)<w$ \textbf{and} $\mathit{high}_1(v)<w$}{
     mark $\{(u,p(u)),(v,p(v)),(w,p(w)),e(u)\}$ as a $4$-cut\;
     \label{line:type3-a-i-special-mark2}
   }   
}
\end{algorithm}
```


